function sumOfGoodSubsequences(nums) {
  const MOD = 1000000007;
  const count = new Map();
  const total = new Map();

  for (const x of nums) {
    const below = count.get(x - 1) ?? 0;
    const above = count.get(x + 1) ?? 0;
    const ways = (1 + below + above) % MOD;
    const carried = ((total.get(x - 1) ?? 0) + (total.get(x + 1) ?? 0)) % MOD;
    const added = (carried + ways * x) % MOD;
    count.set(x, ((count.get(x) ?? 0) + ways) % MOD);
    total.set(x, ((total.get(x) ?? 0) + added) % MOD);
  }

  let answer = 0;
  for (const value of total.values()) {
    answer = (answer + value) % MOD;
  }
  return answer;
}

