function sumOfGoodSubsequences(nums) {
  // Try every non-empty set of indices as a bitmask and add up the elements of each good subsequence.
  const n = nums.length;
  let sum = 0;
  for (let mask = 1; mask < 2 ** n; mask++) {
    let previous = null, elements = 0, good = true;
    for (let i = 0; i < n && good; i++) {
      if (((mask >> i) & 1) === 0) continue;
      if (previous !== null && Math.abs(nums[i] - previous) !== 1) good = false;
      previous = nums[i];
      elements += nums[i];
    }
    if (good) sum += elements;
  }
  return sum % 1000000007;
}

