function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = size === 'large' ? int(1800, 2000) : int(1, 10);
  // Values packed into a narrow window make many neighbours differ by exactly 1.
  const spread = size === 'large' ? int(1, 20) : int(1, 4);
  const pick = rand();
  const base = pick < 0.2 ? 0 : pick < 0.4 ? 100000 - spread : int(0, 100000 - spread);
  return [Array.from({ length }, () => base + int(0, spread))];
}
